import React from "react";
import { BrowserRouter, Link, Navigate, Route, Routes } from "react-router-dom";
import { AuthProvider, useAuth } from "./AuthContext";
import { CartProvider } from "./CartContext";
import { ThemeProvider } from "./ThemeContext";
import { h, f } from "./h";
import {
  ForgotPasswordPage,
  LoginPage,
  RegisterPage,
  ResetPasswordPage,
  VerifyEmailPage
} from "./screensAuth";
import {
  OrdersPage,
  PaymentCancelPage,
  PaymentSuccessPage,
  ProfilePage,
  ShopPage
} from "./screensBuyer";
import {
  VendorAddProductPage,
  VendorAnalyticsPage,
  VendorDashboardPage,
  VendorEditProductPage,
  VendorOrdersPage,
  VendorProductsPage,
  VendorProfilePage,
  VendorReviewsPage,
  VendorSettingsPage,
  VendorShell
} from "./screensVendor";

function VendorGate({ children }) {
  const { accessToken, loading, user } = useAuth();
  if (loading) {
    return h(
      "div",
      { className: "flex min-h-screen items-center justify-center bg-night-950 text-slate-300" },
      "Loading…"
    );
  }
  if (!accessToken) {
    return h(Navigate, { to: "/login", replace: true, state: { from: "vendor" } });
  }
  if (user && user.role && user.role !== "seller") {
    return h(
      "div",
      { className: "mx-auto max-w-md px-4 py-20 text-center" },
      h(
        "div",
        { className: "glass rounded-3xl p-8" },
        [
          h("h1", { className: "text-xl font-bold text-white" }, "Vendor area"),
          h("p", { className: "mt-2 text-sm text-slate-400" }, "Sign in with a vendor account to manage your store."),
          h(
            Link,
            { to: "/register", className: "mt-6 inline-block text-sky-400 hover:underline" },
            "Create a vendor account"
          )
        ]
      )
    );
  }
  return children;
}

function AppRoutes() {
  return h(
    Routes,
    null,
    h(Route, { path: "/", element: h(Navigate, { to: "/shop", replace: true }) }),
    h(Route, { path: "/login", element: h(LoginPage) }),
    h(Route, { path: "/register", element: h(RegisterPage) }),
    h(Route, { path: "/verify-email", element: h(VerifyEmailPage) }),
    h(Route, { path: "/forgot-password", element: h(ForgotPasswordPage) }),
    h(Route, { path: "/reset-password", element: h(ResetPasswordPage) }),
    h(Route, { path: "/shop", element: h(ShopPage) }),
    h(Route, { path: "/orders", element: h(OrdersPage) }),
    h(Route, { path: "/profile", element: h(ProfilePage) }),
    h(Route, { path: "/payment/success", element: h(PaymentSuccessPage) }),
    h(Route, { path: "/payment/cancel", element: h(PaymentCancelPage) }),
    h(
      Route,
      { path: "/vendor", element: h(VendorGate, null, h(VendorShell)) },
      h(Route, { index: true, element: h(Navigate, { to: "dashboard", replace: true }) }),
      h(Route, { path: "dashboard", element: h(VendorDashboardPage) }),
      h(Route, { path: "products", element: h(VendorProductsPage) }),
      h(Route, { path: "products/new", element: h(VendorAddProductPage) }),
      h(Route, { path: "orders", element: h(VendorOrdersPage) }),
      h(Route, { path: "analytics", element: h(VendorAnalyticsPage) }),
      h(Route, { path: "reviews", element: h(VendorReviewsPage) }),
      h(Route, { path: "settings", element: h(VendorSettingsPage) }),
      h(Route, { path: "profile", element: h(VendorProfilePage) })
    ),
    h(Route, { path: "*", element: h(Navigate, { to: "/shop", replace: true }) })
  );
}

export default function App() {
  return h(ThemeProvider, null, [
    h(AuthProvider, null, h(CartProvider, null, h(BrowserRouter, null, h(AppRoutes))))
  ]);
}
